import { readdirSync } from 'node:fs'
import { describe, it, expect } from 'vitest'
import chapterDetachments from './chapterDetachments.js'
import { loadFaction } from './factions/index.js'
import { loadRosterFaction } from './roster/index.js'
import { detachmentsFor } from '../composables/trackerFactions.js'
import { normName } from '../composables/rosterFactionRules.js'

// The faction page offers a Chapter the Codex detachments from this file (useFactionPage.js); the
// roster editor offers them from the roster data. Both are generated by gen-roster-data.mjs, but
// the page finds each one by NAME in another faction's file and silently skips a name it cannot
// find — which is how a Deathwatch player came to see two detachments instead of seventeen.
describe('chapterDetachments', () => {
  const slugs = Object.keys(chapterDetachments)

  it('covers the five Chapters and the Space Marines', () => {
    expect(slugs.sort()).toEqual(['black-templars', 'blood-angels', 'dark-angels', 'deathwatch', 'space-marines', 'space-wolves'])
  })

  it.each(slugs)('%s: every entry is a detachment of the file it is read from', async (slug) => {
    const missing = []
    for (const e of chapterDetachments[slug]) {
      const src = await loadFaction(e.from)
      if (!src?.en.detachments.some((d) => d.name === e.name)) missing.push(`${e.name} (${e.from})`)
    }
    expect(missing).toEqual([])
  })

  // The page shows every detachment printed in the faction's own book; the editor offers only
  // those the army may take. The one difference is a detachment printed for OTHER armies (`lend`
  // in the roster data): Deathwatch Support is read on the Deathwatch page and fielded by the rest.
  const READ_ONLY = { deathwatch: ['Deathwatch Support'] }
  it.each(slugs)('%s: the page offers what the roster editor offers, at the same cost', async (slug) => {
    const own = (await loadFaction(slug)).en.detachments.map((d) => d.name).filter((n) => !READ_ONLY[slug]?.includes(n))
    const roster = await loadRosterFaction(slug)
    const editor = roster.detachments.map((d) => `${d.name} ${d.dp}`).sort()
    const page = []
    for (const name of own) page.push(`${name} ${roster.detachments.find((d) => d.name === name)?.dp}`)
    for (const e of chapterDetachments[slug]) {
      const src = await loadFaction(e.from)
      page.push(`${e.name} ${e.dp ?? src.en.detachments.find((d) => d.name === e.name).dp}`)
    }
    expect(page.sort()).toEqual(editor)
  })
  // Every picker shows the army's own first and the others after them, one group per faction they
  // come from (`from`) — DetachmentGroupHead opens a group wherever `from` changes, so an
  // interleaved list would print the same heading twice.
  const grouped = (list) => {
    const seen = []
    for (const d of list) if (seen.at(-1) !== (d.from || '')) seen.push(d.from || '')
    return seen
  }
  it.each(slugs)('%s: the roster editor and the tracker list their own first, then a group per source', async (slug) => {
    const want = ['', ...new Set(chapterDetachments[slug].map((e) => e.from))]
    expect(grouped((await loadRosterFaction(slug)).detachments)).toEqual(want)
    expect(grouped(detachmentsFor(slug))).toEqual(want)
  })
})

// The roster editor's detachments come from the GW app's entitlements (gen-roster-data.mjs), the
// tracker's from the MFM; two sources answering one question — which detachments can this army
// take — must give one answer. They disagreed on Deathwatch Support for the Deathwatch until
// 2026-10-05 (the editor offered it, the MFM and the app do not), and nothing said so. A
// chapter-locked Codex Supplement detachment is the Space Marines' own in both and is compared too.
describe('the roster editor and the tracker offer the same detachments', () => {
  const factionSlugs = readdirSync('src/data/factions')
    .filter((f) => f.endsWith('.js') && f !== 'index.js').map((f) => f.replace(/\.js$/, ''))
  it.each(factionSlugs)('%s', async (slug) => {
    // Compared as the app compares them (normName): the MFM writes "Data-psalm", appdata "Data-Psalm".
    const editor = (await loadRosterFaction(slug)).detachments.map((d) => normName(d.name)).sort()
    const tracker = detachmentsFor(slug).map((d) => normName(d.name)).sort()
    expect(editor).toEqual(tracker)
  })
})
